package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MapType.construct
 */
public class MapType_construct_TriageGen1Test {

    private final TypeFactory typeFactory = TypeFactory.defaultInstance();

    @Test
    public void testConstruct_WithTwoTypeParameters() {
        // Case where vars.length == 2 (e.g., Map.class)
        Class<?> rawType = Map.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());
        // Verify bindings are not empty since it's a Map (2 params)
        assertNotEquals(TypeBindings.emptyBindings(), result.getTypeBindings());
    }

    @Test
    public void testConstruct_WithZeroTypeParameters() {
        // Case where vars.length == 0 (e.g., HashMap.class if treated as raw, 
        // but HashMap actually has 0 type parameters in its definition)
        Class<?> rawType = HashMap.class;
        JavaType keyType = typeFactory.constructType(Object.class);
        JavaType valueType = typeFactory.constructType(Object.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());
        // Should use empty bindings because vars.length != 2
        assertEquals(TypeBindings.emptyBindings(), result.getTypeBindings());
    }

    @Test
    public void testConstruct_WithOneTypeParameter() {
        // Mocking a class with exactly 1 type parameter to trigger the else branch for (vars.length != 2)
        class SingleParam<T> {}
        Class<?> rawType = SingleParam.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(TypeBindings.emptyBindings(), result.getTypeBindings());
    }

    @Test
    public void testConstruct_WithThreeTypeParameters() {
        // Mocking a class with 3 type parameters to trigger the else branch for (vars.length != 2)
        class TripleParam<A, B, C> {}
        Class<?> rawType = TripleParam.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(TypeBindings.emptyBindings(), result.getTypeBindings());
    }

    @Test
    public void testConstruct_WithNullRawType() {
        // Testing the (vars == null) branch
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        // Note: passing null to rawType.getTypeParameters() will throw NPE in real scenarios,
        // but the code checks (vars == null). If rawType is null, rawType.getTypeParameters() throws NPE.
        // However, if we assume the check is for the result of getTypeParameters():
        try {
            MapType result = MapType.construct(null, keyType, valueType);
            assertNull(result);
        } catch (NullPointerException e) {
            // Expected behavior if rawType is null because we can't call getTypeParameters()
        }
    }
}
